import{_ as s,o as t,c as a,ak as i}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"Fix plans, reproduce & bisect","description":"","frontmatter":{"title":"Fix plans, reproduce & bisect","lang":"en-US"},"headers":[],"relativePath":"features/fix-plans.md","filePath":"features/fix-plans.md","lastUpdated":1788707566000}'),n={name:"features/fix-plans.md"};function o(r,e,h,l,d,p){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="fix-plans-reproduce-bisect" tabindex="-1">Fix plans, reproduce &amp; bisect <a class="header-anchor" href="#fix-plans-reproduce-bisect" aria-label="Permalink to &quot;Fix plans, reproduce &amp; bisect&quot;">​</a></h1><p>A <strong>fix plan</strong> gathers everything Piwi knows about a failure cluster into one answer to &quot;what do I do about this?&quot; — the <a href="./ai-diagnosis.html">AI diagnosis</a> and its validated patch, the ranked <a href="./ai-diagnosis.html#locator-healing">locator replacement</a> with the exact file and line to edit, the failing tests, the owning team, and the command that verifies the work. None of it needs a model of its own: a cluster with no AI diagnosis still returns its failing tests, its locator suggestions and its verification command, so the plan is useful with no AI provider configured at all.</p><h2 id="where-to-get-it" tabindex="-1">Where to get it <a class="header-anchor" href="#where-to-get-it" aria-label="Permalink to &quot;Where to get it&quot;">​</a></h2><p>The same plan is reachable three ways:</p><ul><li><strong>On the cluster page</strong> — the cluster&#39;s single <strong>Fix</strong> card gathers the diagnosis and its patch (copy, <code>git apply</code>, download), the recommended locator fix, the verify command, and a <strong>Copy as Markdown</strong> action that hands you the whole plan for a ticket. <strong>Re-run in CI</strong> is the page&#39;s header action when that is configured. The failing tests are the page&#39;s <strong>Affected tests</strong> list and the owner is on the header&#39;s facts line, so the plan is assembled from the page you&#39;re already reading rather than duplicated in a card of its own.</li><li><strong>As Markdown</strong> — <code>GET /api/failure-clusters/:id/fix-plan?format=markdown</code> returns the same rendering as plain text, so an export or a script can drop it straight into an issue.</li><li><strong>For agents</strong> — the <code>get_fix_plan</code> <a href="/features/mcp.html">MCP tool</a> returns the structured plan, so a coding agent gets in one call what a person reads on the card.</li></ul><p>The last part is what makes it a loop rather than a lookup: the plan states which Playwright command runs exactly the affected tests, and that Piwi will record the fix once they pass — so an agent (or a person) can confirm the work instead of leaving someone to decide whether it landed. Nothing leaves your machine: the dashboard is yours, the model is whichever one you configured (including a local one), and the patch was validated against your own source before you saw it.</p><h2 id="reproduce-and-bisect" tabindex="-1">Reproduce and bisect <a class="header-anchor" href="#reproduce-and-bisect" aria-label="Permalink to &quot;Reproduce and bisect&quot;">​</a></h2><p>The fix plan also hands back the two things you do next: a copy-paste recipe that reproduces the failure locally, and a generated <code>git bisect</code> that finds the commit that broke it. Both sit in a <strong>Reproduce</strong> section on the Fix card — on the cluster page and on the failing <a href="./evidence.html#one-execution-diagnosis-first">execution&#39;s page</a> — and travel with the plan through <code>?format=markdown</code> and the <code>get_fix_plan</code> MCP tool.</p><p>The <strong>recipe</strong> is the local reproduction, in order: check out the commit the run failed on (<code>git switch --detach &lt;sha&gt;</code>), install dependencies, pin Playwright to the version the run used, install the browser it ran on, and run exactly the failing test. Each part degrades on its own — no recorded commit skips the checkout and says so, an unknown Playwright version drops the pin — and the run&#39;s environment (label, base URL) is listed beside it. Every command is <code>git</code>, <code>npm</code> or <code>npx</code>, so it is identical on Linux, macOS and Windows; the dashboard still offers a <strong>Linux / macOS</strong> and a <strong>Windows (PowerShell)</strong> tab so a reader copies the form they expect.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check out the failing commit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --detach</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9a8b7c6d5e4f30211203f4e5d6c7b8a99a8b7c6d</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install dependencies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Pin Playwright to the run&#39;s version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @playwright/test@1.52.0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install the browser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run the failing test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tests/admin/users.spec.ts&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Chromium&quot;</span></span></code></pre></div><p>The <strong>bisect</strong> walks the commits between the last green run and the failing one, re-running the test at each step — a non-zero exit marks a commit bad — until it names the first commit that broke it, then <code>git bisect reset</code> returns you to where you started.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bisect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">failing-commi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">last-green-commi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bisect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tests/admin/users.spec.ts&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Users table paginates 25 rows per page&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bisect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span></span></code></pre></div><p>The bisect needs a <strong>last-green commit</strong> and an <strong>SCM connection</strong>: when Piwi has no commit for the failing run or for the last green run before it, or the two are the same commit, the section says so in one line instead of showing a script. The recipe is always there.</p><p>In the <a href="/features/desktop.html#reproducing-a-failure-and-finding-the-breaking-commit">desktop app</a> the same section can also do the work for you: <strong>Reproduce here</strong> runs the recipe against the linked folder in a throwaway <code>git worktree</code> — your checkout is never touched — and <strong>Find the breaking commit here</strong> drives the whole bisect step by step, with live progress and a stop that stops, then records the first bad commit on the cluster so it shows here and in the fix plan afterwards.</p><h2 id="fixed-before" tabindex="-1">Fixed before <a class="header-anchor" href="#fixed-before" aria-label="Permalink to &quot;Fixed before&quot;">​</a></h2><p>An open cluster often isn&#39;t new — the same failure, or one close to it, was fixed weeks ago. The fix plan looks back over the project&#39;s <strong>resolved</strong> clusters (resolved, or with a verified fix that held) and, when one resembles the open cluster closely enough, shows it in a <strong>Fixed before</strong> section on the Fix card — on the cluster page and on the failing execution&#39;s page, and in the <code>?format=markdown</code> export and the <code>get_fix_plan</code> MCP tool.</p><p>A match is scored deterministically first — the same fingerprint family (error kind, masked message, masked locator), the same failing locator, the same spec file or test — and then, when an <a href="./ai-diagnosis.html#model-roles">embedding model</a> is configured, by semantic similarity of the stored cluster vectors. The top three matches are shown, each with <strong>when</strong> it was resolved, the <strong>commit</strong> that fixed it (linked when the repository host is known), <strong>how long</strong> it stayed open, the triage note, the owner, the earlier diagnosis and its thumbs feedback, and one short reason it matched (&quot;same error and locator&quot;, &quot;same spec, similar message (0.91)&quot;). Nothing matches → the section renders nothing, no empty-state noise.</p><p><strong>Apply the same triage</strong> copies the earlier cluster&#39;s triage note onto the open one, prefixed <code>Same as cluster #N:</code> so the history reads as an intentional reuse. It never changes the open cluster&#39;s status — a new cluster is never marked resolved just because an old one was. The same top match is fed to the AI diagnosis as a <em>Previously fixed similar failure</em> clue, so the model can reuse a known fix rather than re-derive it.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./ai-diagnosis.html">AI diagnosis &amp; failure clustering</a> — the diagnosis and validated patch a fix plan wraps</li><li><a href="./failure-clusters.html">Failure clusters &amp; the inbox</a> — the clusters a fix plan is attached to</li><li><a href="./auto-heal.html">Auto-heal PRs</a> — when Piwi opens the locator fix as a pull request itself</li><li><a href="/features/mcp.html">MCP server</a> — the <code>get_fix_plan</code> tool</li><li><a href="/features/desktop.html#reproducing-a-failure-and-finding-the-breaking-commit">Desktop app</a> — run the recipe and drive the bisect locally</li></ul>`,20)])])}const k=s(n,[["render",o]]);export{g as __pageData,k as default};
